/**
 * ユーザーが安全でない場所を選択しないようにし、適切な保存場所を選択するか操作をキャンセルするまでダイアログを表示します。
 * @param showDialogFunction ダイアログを表示する関数
 */
const retryShowSaveDialogUntilValid = async <
  T extends Electron.OpenDialogReturnValue | Electron.SaveDialogReturnValue
>(
  showDialogFunction: () => Promise<T>
): Promise<T> => {
  const unsafeDirs = [appDirPath, app.getPath("userData")];

  while (true) {
    const result = await showDialogFunction();
    // キャンセルされた場合、結果を直ちに返す
    if (result.canceled) return result;

    // 選択されたファイルパスを取得
    const filePath = result.filePaths ? result.filePaths[0] : result.filePath;
    if (!filePath) return result; // filePathが未定義の場合、結果を返す

    // 選択されたパスが安全かどうかを確認
    if (isPathUnsafe(filePath, unsafeDirs)) {
      const shouldRetry = await showWarningDialog();
      if (!shouldRetry) return result; // ユーザーが警告を無視して保存を選択した場合
    } else {
      return result; // 安全なパスが選択された場合
    }
  }
};

/**
 * 指定されたパスが安全でないかどうかを判断します。
 */
const isPathUnsafe = (filePath, unsafeDirs) => {
  return unsafeDirs.some(unsafeDir => {
    const relativePath = path.relative(unsafeDir, filePath);
    return !path.isAbsolute(relativePath) && !relativePath.startsWith('..');
  });
};

/**
 * 警告ダイアログを表示し、ユーザーが再試行を選択したかどうかを返します。
 */
const showWarningDialog = async () => {
  const warningResult = await dialog.showMessageBox(win, {
    message: "指定された保存先は自動的に削除される可能性があります。",
    type: "warning",
    buttons: ["保存場所を変更", "無視して保存"],
    defaultId: 0,
    title: "警告",
    detail: "本当にこの場所に保存しますか？",
    cancelId: 0,
  });
  return warningResult.response === 0; // 0: 再試行, 1: 無視して保存
};

